import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-chicken-rabbit-adv.svg",g=JSON.parse('{"title":"小学奥数经典：鸡兔同笼的各种巧解","description":"鸡兔同笼不仅是古代数学名题，更是培养逻辑思维的绝佳素材。本文教你如何用假设法、抬腿法轻松破解。","frontmatter":{"title":"小学奥数经典：鸡兔同笼的各种巧解","date":"2026-02-08T09:30:00.000Z","categories":["数学"],"tags":["小学数学","奥数","鸡兔同笼"],"description":"鸡兔同笼不仅是古代数学名题，更是培养逻辑思维的绝佳素材。本文教你如何用假设法、抬腿法轻松破解。","cover":"/img/math-chicken-rabbit-adv.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-chicken-rabbit-adv.md","filePath":"posts/primary-math-olympiad-chicken-rabbit-adv.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-chicken-rabbit-adv.md"};function e(r,a,o,c,i,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数经典-鸡兔同笼的各种巧解" tabindex="-1">小学奥数经典：鸡兔同笼的各种巧解 <a class="header-anchor" href="#小学奥数经典-鸡兔同笼的各种巧解" aria-label="Permalink to &quot;小学奥数经典：鸡兔同笼的各种巧解&quot;">​</a></h1><h2 id="一、-经典原题" tabindex="-1">一、 经典原题 <a class="header-anchor" href="#一、-经典原题" aria-label="Permalink to &quot;一、 经典原题&quot;">​</a></h2><blockquote><p>“今有雉兔同笼，上有三十五头，下有九十四足，问雉兔各几何？”</p></blockquote><p>这是《孙子算经》中的名题：笼子里有鸡和兔，头有 35 个，脚有 94 只。问鸡和兔各有多少只？</p><hr><h2 id="二、-核心解法-假设法" tabindex="-1">二、 核心解法：假设法 <a class="header-anchor" href="#二、-核心解法-假设法" aria-label="Permalink to &quot;二、 核心解法：假设法&quot;">​</a></h2><p>假设法是解决此类问题的万能钥匙。</p><h3 id="步骤详解" tabindex="-1">步骤详解： <a class="header-anchor" href="#步骤详解" aria-label="Permalink to &quot;步骤详解：&quot;">​</a></h3><ol><li><strong>全部假设</strong>：假设 35 只全是鸡。</li><li><strong>计算足数</strong>：应该是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>5</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>7</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">35 \\times 2 = 70</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span></span></span></span> 只脚。</li><li><strong>寻找差异</strong>：实际有 94 只脚，比假设多了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>4</mn><mo>−</mo><mn>7</mn><mn>0</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">94 - 70 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span> 只脚。</li><li><strong>分析原因</strong>：因为我们把兔子当成了鸡。每只兔子比鸡多 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">4 - 2 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 只脚。</li><li><strong>求出兔数</strong>：多出的 24 只脚里，包含了几只兔子？ <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>4</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">24 \\div 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> 只。</li><li><strong>求出鸡数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>5</mn><mo>−</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>2</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">35 - 12 = 23</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span></span></span></span> 只。</li></ol><p><img src="'+p+'" alt="鸡兔同笼假设法图解"></p><hr><h2 id="三、-趣味解法-抬腿法-吹哨法" tabindex="-1">三、 趣味解法：抬腿法（吹哨法） <a class="header-anchor" href="#三、-趣味解法-抬腿法-吹哨法" aria-label="Permalink to &quot;三、 趣味解法：抬腿法（吹哨法）&quot;">​</a></h2><p>想象一下，你吹一声哨子，所有的动物都抬起两条腿：</p><ol><li><strong>第一次抬腿</strong>：每只动物抬起 2 条腿。</li><li><strong>地上的腿</strong>：少了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>5</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>7</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">35 \\times 2 = 70</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span></span></span></span> 条腿，剩下 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>4</mn><mo>−</mo><mn>7</mn><mn>0</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">94 - 70 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span> 条腿。</li><li><strong>观察现状</strong>：此时，鸡的两条腿全抬起来了（一屁股坐在地上），兔子的两条腿抬起来了，还剩两条腿站着。</li><li><strong>结论</strong>：地上的 24 条腿全是兔子的，且每只兔子剩 2 条腿。所以兔数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>2</mn><mn>4</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">= 24 \\div 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> 只。</li></ol><hr><h2 id="四、-进阶变式-不仅仅是鸡和兔" tabindex="-1">四、 进阶变式：不仅仅是鸡和兔 <a class="header-anchor" href="#四、-进阶变式-不仅仅是鸡和兔" aria-label="Permalink to &quot;四、 进阶变式：不仅仅是鸡和兔&quot;">​</a></h2><p>“鸡兔同笼”是一种<strong>模型</strong>，可以应用在很多生活场景中。</p><h3 id="_1-租船问题" tabindex="-1">1. 租船问题 <a class="header-anchor" href="#_1-租船问题" aria-label="Permalink to &quot;1. 租船问题&quot;">​</a></h3><p><strong>例题</strong>：42 名同学去划船，共租了 10 条船。大船坐 5 人，小船坐 3 人。问大船和小船各租了几条？</p><ul><li><strong>类比</strong>：大船是“兔”（5只脚），小船是“鸡”（3只脚），人是“脚”，船是“头”。</li><li><strong>假设全租小船</strong>：应坐 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>3</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">10 \\times 3 = 30</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span></span></span></span> 人。</li><li><strong>少算的人数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>2</mn><mo>−</mo><mn>3</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">42 - 30 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> 人。</li><li><strong>每条船差额</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">5 - 3 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 人。</li><li><strong>大船数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">12 \\div 2 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 条。</li><li><strong>小船数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">10 - 6 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 条。</li></ul><h3 id="_2-考试得分" tabindex="-1">2. 考试得分 <a class="header-anchor" href="#_2-考试得分" aria-label="Permalink to &quot;2. 考试得分&quot;">​</a></h3><p><strong>例题</strong>：一次数学竞赛共 20 题。做对一题得 5 分，做错一题扣 2 分。小明得了 79 分，他做对了几题？</p><ul><li><strong>分析</strong>：这是一个“变种”鸡兔同笼。</li><li><strong>假设全做对</strong>：应得 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 5 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span> 分。</li><li><strong>少的分数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>7</mn><mn>9</mn><mo>=</mo><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">100 - 79 = 21</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span> 分。</li><li><strong>差额</strong>：做错一题不仅不得 5 分，还要扣 2 分，一进一出差了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">5 + 2 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span> 分！</li><li><strong>错题数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>1</mn><mo>÷</mo><mn>7</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">21 \\div 7 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">1</span><span class="mbin">÷</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span> 题。</li><li><strong>对题数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">20 - 3 = 17</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">7</span></span></span></span> 题。</li></ul><hr><h2 id="五、-总结口诀" tabindex="-1">五、 总结口诀 <a class="header-anchor" href="#五、-总结口诀" aria-label="Permalink to &quot;五、 总结口诀&quot;">​</a></h2><blockquote><p><strong>假鸡求兔，假兔求鸡。</strong><strong>多出脚数，除以差值。</strong><strong>模型通用，思维第一！</strong></p></blockquote><hr><h2 id="六、-举一反三-练习题" tabindex="-1">六、 举一反三（练习题） <a class="header-anchor" href="#六、-举一反三-练习题" aria-label="Permalink to &quot;六、 举一反三（练习题）&quot;">​</a></h2><ol><li>一个停车场停了自行车和三轮车共 15 辆，共有 38 个轮子。问自行车和三轮车各有多少辆？</li><li>储蓄罐里有 5 角和 1 元的硬币共 30 枚，总面值 22 元。问两种硬币各有多少枚？</li></ol><hr><p><em>提示：不管题目怎么变，只要有“两种对象”和“两种总量”，就可以用鸡兔同笼模型！</em></p>',31)])])}const x=s(l,[["render",e]]);export{g as __pageData,x as default};
